import json
import os
from typing import Any, Dict, List

class ResultValidator:
    """Validates the output assets generated by the pipeline execution."""

    @classmethod
    def validate_outputs(cls, pipeline_results: Dict[str, Any]) -> List[str]:
        """Validates all output files and transcript alignments.
        
        Args:
            pipeline_results (Dict[str, Any]): Execution output paths dictionary.
            
        Returns:
            List[str]: List of failure error logs (empty if valid).
        """
        errors = []
        
        # 1. Verify existence of files
        asset_keys = [
            "video_path", "audio_path", "transcript_path", 
            "translated_path", "aligned_path", "final_wav", "final_mp3"
        ]
        
        for key in asset_keys:
            path = pipeline_results.get(key)
            if not path or not os.path.exists(path):
                errors.append(f"Missing pipeline output asset path for key '{key}': {path}")
            elif os.path.getsize(path) == 0:
                errors.append(f"Empty (zero-byte) file generated for key '{key}': {path}")
                
        # 2. Check metadata
        meta = pipeline_results.get("metadata", {})
        if not meta or not meta.get("duration") or meta.get("duration") <= 0:
            errors.append(f"Invalid duration field in metadata: {meta.get('duration')}")
            
        # 3. Check aligned transcript structure
        aligned_path = pipeline_results.get("aligned_path")
        if aligned_path and os.path.exists(aligned_path):
            try:
                with open(aligned_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                segments = data.get("segments", [])
                if not segments:
                    errors.append("Aligned transcript contains no segment objects.")
                
                prev_end = 0.0
                for idx, seg in enumerate(segments):
                    if seg.get("id") != idx:
                        errors.append(f"Segment ID mismatch: expected {idx}, got {seg.get('id')}")
                    if idx > 0 and seg.get("start") < prev_end:
                        errors.append(
                            f"Overlapping timestamps in segment ID {seg.get('id')}: "
                            f"start {seg.get('start')} is less than prev_end {prev_end}"
                        )
                    prev_end = seg.get("end", 0.0)
            except Exception as e:
                errors.append(f"Failed to parse aligned transcript JSON file: {str(e)}")
                
        return errors
